async ({ page, baseUrl, expect }) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  const writes = [];
  page.on('request', request => { if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method())) writes.push(request.method() + ' ' + request.url()); });
  await page.goto(baseUrl);
  await expect(page.getByRole('heading', { name: 'Account', exact: true })).toBeVisible();
  const plan = page.getByRole('region', { name: 'Team plan', exact: true });
  const summary = plan.getByText('View plan details', { exact: true });
  const heading = plan.getByRole('heading', { name: 'Plan details', exact: true });
  const lines = ['Billing cycle: Monthly', 'Price: $48 per month', 'Included seats: 20'];
  await expect(summary).toBeVisible();
  await expect(summary).toHaveAccessibleName('View plan details');
  expect(await summary.evaluate(element => ({ tag: element.localName, parent: element.parentElement?.localName }))).toEqual({ tag: 'summary', parent: 'details' });
  await expect(heading).not.toBeVisible();
  for (const line of lines) await expect(plan.getByText(line, { exact: true })).not.toBeVisible();
  await summary.click();
  await expect(heading).toBeVisible();
  for (const line of lines) await expect(plan.getByText(line, { exact: true })).toBeVisible();
  await summary.click();
  await expect(heading).not.toBeVisible();
  for (const line of lines) await expect(plan.getByText(line, { exact: true })).not.toBeVisible();
  await summary.click();
  await expect(heading).toBeVisible();
  for (const line of lines) await expect(plan.getByText(line, { exact: true })).toBeVisible();
  expect(writes).toEqual([]);
}

async ({ page, baseUrl, expect }) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto(baseUrl);
  const summary = page.getByRole('region', { name: 'Team plan', exact: true }).getByText('View plan details', { exact: true });
  const heading = page.getByRole('heading', { name: 'Plan details', exact: true });
  await expect(summary).toBeVisible();
  await expect(summary).toHaveAccessibleName('View plan details');
  await expect(heading).not.toBeVisible();
  for (let step = 0; step < 8; step += 1) {
    await page.keyboard.press('Tab');
    if (await summary.evaluate(element => element === document.activeElement)) break;
  }
  await expect(summary).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(heading).toBeVisible();
  await expect(page.getByText('Price: $48 per month', { exact: true })).toBeVisible();
  await expect(summary).toBeFocused();
  await page.keyboard.press('Space');
  await expect(heading).not.toBeVisible();
  await expect(summary).toBeFocused();
  await page.keyboard.press('Space');
  await expect(heading).toBeVisible();
  await expect(page.getByText('Included seats: 20', { exact: true })).toBeVisible();
  await expect(summary).toBeFocused();
}

async ({ page, baseUrl, expect }) => {
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto(baseUrl);
  await expect(page.getByRole('heading', { name: 'Account', exact: true })).toBeVisible();
  await expect(page.getByText('Alex Rivera', { exact: true })).toBeVisible();
  await expect(page.getByText('alex.rivera@example.test', { exact: true })).toBeVisible();
  const summary = page.getByRole('region', { name: 'Team plan', exact: true }).getByText('View plan details', { exact: true });
  const heading = page.getByRole('heading', { name: 'Plan details', exact: true });
  await expect(summary).toBeVisible();
  await expect(heading).not.toBeVisible();
  await summary.click();
  await expect(heading).toBeVisible();
  await summary.click();
  await expect(heading).not.toBeVisible();
  await summary.click();
  await expect(heading).toBeVisible();
  for (const text of ['Billing cycle: Monthly', 'Price: $48 per month', 'Included seats: 20']) {
    const line = page.getByText(text, { exact: true });
    await expect(line).toBeVisible();
    await line.scrollIntoViewIfNeeded();
    const bounds = await line.boundingBox();
    expect(bounds).not.toBeNull();
    expect(bounds.x).toBeGreaterThanOrEqual(0);
    expect(bounds.x + bounds.width).toBeLessThanOrEqual(375);
  }
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
  await heading.scrollIntoViewIfNeeded();
}

async ({ page, baseUrl, expect }) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto(baseUrl);
  await page.getByText('View plan details', { exact: true }).click();
  await expect(page.getByRole('heading', { name: 'Plan details', exact: true })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'Personal details', exact: true })).toBeVisible();
  for (const text of ['Alex Rivera', 'alex.rivera@example.test', 'Workspace administrator', 'North America', 'Account active', 'Renews on September 18, 2026']) {
    await expect(page.getByText(text, { exact: true })).toBeVisible();
  }
  await expect(page.getByRole('progressbar', { name: '12 of 20 seats used' })).toHaveAttribute('aria-valuenow', '12');
  await expect(page.getByRole('heading', { name: 'Security posture', exact: true })).toBeVisible();
  for (const text of ['Email verified', 'Two-step verification enabled', 'Recovery contact configured']) {
    await expect(page.getByText(text, { exact: false })).toBeVisible();
  }
  const account = page.getByRole('navigation', { name: 'Primary navigation' }).getByRole('link', { name: 'Account', exact: true });
  await expect(account).toHaveAttribute('aria-current', 'page');
  await account.click();
  await expect(page.getByRole('heading', { name: 'Account', exact: true })).toBeVisible();
  await page.goto(new URL('/qa-plan-missing-page', baseUrl).href);
  await expect(page.getByRole('heading', { name: 'Page not found', exact: true })).toBeVisible();
  await page.getByRole('link', { name: 'Return to Account', exact: true }).click();
  await expect(page.getByRole('heading', { name: 'Account', exact: true })).toBeVisible();
  await page.getByRole('link', { name: 'QA Lab home', exact: true }).click();
  await expect(page.getByRole('heading', { name: 'Account', exact: true })).toBeVisible();
  await expect(page.getByText('View plan details', { exact: true })).toBeVisible();
}
